package lr2touch;
import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.concurrent.atomic.AtomicInteger;import java.util.function.Function;
public final class BattleHttpVerify {
 static String request(String url,String method,String body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestMethod(method);c.setConnectTimeout(2000);c.setReadTimeout(2000);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");c.getOutputStream().write(body.getBytes(StandardCharsets.UTF_8));}int status=c.getResponseCode();String text=new String((status<400?c.getInputStream():c.getErrorStream()).readAllBytes(),StandardCharsets.UTF_8);return status+" "+text;}
 public static void main(String[] args)throws Exception{AtomicInteger calls=new AtomicInteger();Path root=Paths.get("work/battle-release/Subscreen/battle-overlay");try(BattleHttp http=new BattleHttp(0,root,()->"{\"phase\":\"LOBBY\"}",a->{calls.incrementAndGet();return a.equals("p1");},"secret-pass",false)){String base="http://127.0.0.1:"+http.port();String page=request(base+"/control.html","GET",null);if(!page.contains("ADMIN LOGIN"))throw new AssertionError("Control UI missing");if(!request(base+"/command","POST","user=admin&password=bad&action=p1").startsWith("403"))throw new AssertionError("Bad password accepted");if(calls.get()!=0)throw new AssertionError("Unauthenticated command executed");if(!request(base+"/command","POST","user=operator&password=secret-pass&action=p1").startsWith("403"))throw new AssertionError("Wrong user accepted");if(!request(base+"/command","POST","user=admin&password=secret-pass&action=p1").startsWith("200"))throw new AssertionError("Admin command rejected");if(calls.get()!=1)throw new AssertionError("Authorized command not executed exactly once");System.out.println("PASS: admin web control authentication and command routing");}}
}
